check.python:
messages = ["Güçlüsün", "Dikkatli ol", "İksir iç!"]
for value, expected in [(80, "Güçlüsün"), (50, "Dikkatli ol"), (10, "İksir iç!"), (25, "İksir iç!")]:
    out, _ = _run(_set(_code, "hp", value))
    assert expected in out, "hp = " + str(value) + " olunca '" + expected + "' yazmalı."
    for other in messages:
        if other != expected:
            assert other not in out, "hp = " + str(value) + " olunca sadece '" + expected + "' yazmalı."

