visual_task.solution:
can = 3

if can >= 3:
    print("HHH")
elif can == 2:
    print("HH")
elif can == 1:
    print("H")
else:
    print("Oyun bitti!")

check.python:
for deger, beklenen in [(3, "HHH"), (5, "HHH"), (2, "HH"), (1, "H"), (0, "Oyun bitti!"), (-2, "Oyun bitti!")]:
    out, _ = _run(_set(_code, "can", deger))
    assert out.strip() == beklenen, "can = {} iken çıktı {} olmalı. Senin çıktın: {}".format(deger, beklenen, out.strip() or "(boş)")

